{"seats": {"A": 5, "B": 3, "C": 3}, "threshold": 6}

@minimal jsEval
const names = Object.keys($slots.seats);
const subsets = [];
for (let mask = 1; mask < (1 << names.length); mask++) {
  const members = names.filter((_, index) => mask & (1 << index));
  subsets.push(members);
}
const winning = subsets.filter((members) => members.reduce((sum, name) => sum + $slots.seats[name], 0) >= $slots.threshold);
const minimal = winning.filter((members) => members.every((member) => {
  const rest = members.filter((name) => name !== member);
  const restSeats = rest.reduce((sum, name) => sum + $slots.seats[name], 0);
  return restSeats < $slots.threshold;
}));
return minimal;

@answer jsEval
const labels = $minimal.map((members) => "{" + members.join(",") + "}");
return "The minimal winning coalitions are " + labels.join(", ") + ".";
```

